	return 0
}

func (m *Meta) fmt(c *FmtCommand, paths []string, stdout io.Writer) tfdiags.Diagnostics {
	var diags tfdiags.Diagnostics
	var parser *configs.Parser

	if _, err := m.initConfigLoader(); err == nil && m.configLoader != nil {
		parser = m.configLoader.Parser()
	}

	if len(paths) == 0 { // Assuming stdin, then.
		if c.write {
			diags = diags.Append(fmt.Errorf("Option -write cannot be used when reading from stdin"))
			return diags
		}
		fileDiags := formatOneFile(c, parser, "<stdin>", c.input, stdout, c.list, c.write, c.diff)
		diags = diags.Append(fileDiags)
		return diags
	}

	m.fixupMissingWorkingDir()
	for _, path := range paths {
		path = m.WorkingDir.NormalizePath(path)
		info, err := os.Stat(path)
